<?php
require __DIR__.'/includes/bootstrap.php';require_login();$page_title='Sell an item';$error='';$categories=['Phones & Tablets','Computers','Electronics','Fashion','Home & Furniture','Vehicles','Property','Jobs & Services','Other'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$loc=trim($_POST['location']??'');$cat=$_POST['category']??'Other';$cond=$_POST['condition_type']??'Used';$image=null;
 if(!$title||!$desc||$price<=0||!$loc){$error='Please complete all required fields and enter a price above zero.';}
 elseif(!in_array($cat,$categories,true)||!in_array($cond,['Used','Brand New'],true)){$error='Please choose valid category and condition.';}
 else {if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']!==UPLOAD_ERR_OK||!isset($allowed[$mime])||$f['size']>5*1024*1024){$error='Upload a JPG, PNG or WEBP image under 5MB.';}else{$image=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$image)){$error='Could not save the image.';}}}
 if(!$error){$st=db()->prepare('INSERT INTO products(user_id,title,description,price,location,category,condition_type,image) VALUES(?,?,?,?,?,?,?,?)');$st->execute([current_user()['id'],$title,$desc,$price,$loc,$cat,$cond,$image]);flash('Your item is now listed.');header('Location: '.url('product.php?id='.db()->lastInsertId()));exit;}}
}
include __DIR__.'/includes/header.php'; ?>
<div class="form-wrap form-wide"><span class="eyebrow">REACH YOUR NEXT BUYER</span><h1>Post an item for sale</h1><p class="muted">Add clear details so buyers know exactly what you're offering.</p><?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="form-card"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Item title<input name="title" maxlength="150" required placeholder="e.g. Samsung Galaxy S22"></label><label>Description<textarea name="description" rows="5" required></textarea></label><div class="two-col"><label>Price (NGN)<input type="number" name="price" min="1" step="1" required></label><label>Location<input name="location" required placeholder="e.g. Ikeja, Lagos"></label></div><div class="two-col"><label>Category<select name="category"><?php foreach($categories as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></label><label>Condition<select name="condition_type"><option>Used</option><option>Brand New</option></select></label></div><label>Product photo (JPG, PNG or WEBP; max 5MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><button class="btn wide">Publish listing</button></form></div>
<?php include __DIR__.'/includes/footer.php'; ?>
